"""
Verification Agent and Autonomous Document Classifier.
Implements model chaining, mathematical consistency audits, and confidence scoring.
"""

import logging
from typing import Any, Dict, List, Literal, Optional, Tuple
from pydantic import BaseModel, Field

logger = logging.getLogger("extractor.verification")


class VerificationReport(BaseModel):
    """Audit report generated by the verification agent."""
    confidence_score: float = Field(
        default=0.95,
        ge=0.0,
        le=1.0,
        description="Overall confidence score for the extraction (0.0 to 1.0)",
    )
    math_verified: Optional[bool] = Field(
        default=None,
        description="True if line-item math and totals reconcile mathematically",
    )
    math_details: Optional[str] = Field(
        default=None,
        description="Explanation of mathematical consistency check",
    )
    warnings: List[str] = Field(
        default_factory=list,
        description="Non-breaking anomalies or observations detected during audit",
    )
    detected_fields_count: int = Field(
        default=0,
        description="Number of non-null extracted fields",
    )


class VerificationAgent:
    """Agentic verification system performing post-extraction fact and math checks."""

    @classmethod
    def audit_extraction(cls, document_type: str, data: Dict[str, Any]) -> VerificationReport:
        """Run domain-specific verification rules over extracted data."""
        doc_type = document_type.lower().strip()
        warnings: List[str] = []
        math_verified: Optional[bool] = None
        math_details: Optional[str] = None

        # Count extracted non-empty fields
        detected_fields = sum(
            1 for v in data.values()
            if v is not None and v != [] and v != ""
        )

        if doc_type == "invoice":
            math_verified, math_details, invoice_warnings = cls._audit_invoice(data)
            warnings.extend(invoice_warnings)

        elif doc_type == "receipt":
            math_verified, math_details, receipt_warnings = cls._audit_receipt(data)
            warnings.extend(receipt_warnings)

        elif doc_type == "resume":
            resume_warnings = cls._audit_resume(data)
            warnings.extend(resume_warnings)

        # Compute confidence score
        confidence = 0.98
        if math_verified is False:
            confidence -= 0.15
        if warnings:
            confidence -= min(0.05 * len(warnings), 0.20)
        if detected_fields < 3:
            confidence -= 0.20

        confidence = max(0.50, min(1.0, round(confidence, 2)))

        return VerificationReport(
            confidence_score=confidence,
            math_verified=math_verified,
            math_details=math_details,
            warnings=warnings,
            detected_fields_count=detected_fields,
        )

    @classmethod
    def _audit_invoice(cls, data: Dict[str, Any]) -> Tuple[Optional[bool], Optional[str], List[str]]:
        warnings: List[str] = []
        total_amount = data.get("total_amount")
        line_items = data.get("line_items") or []

        if not data.get("invoice_number"):
            warnings.append("Invoice identifier was not explicitly stated in document.")

        if not data.get("invoice_date"):
            warnings.append("Invoice date was missing or not deterministically parseable.")

        if total_amount is not None and line_items:
            calculated_subtotal = sum(
                (item.get("line_total") or (item.get("quantity", 0) * (item.get("unit_price") or 0)))
                for item in line_items
                if isinstance(item, dict)
            )
            # Allow tolerance for tax/rounding
            if calculated_subtotal > 0:
                diff = abs(total_amount - calculated_subtotal)
                if diff < 0.05:
                    return True, f"Sum of line items ({calculated_subtotal:,.2f}) perfectly equals grand total ({total_amount:,.2f}).", warnings
                elif calculated_subtotal <= total_amount:
                    return True, f"Line items subtotal ({calculated_subtotal:,.2f}) reconciles with grand total ({total_amount:,.2f}) with applied tax/shipping.", warnings
                else:
                    warnings.append(f"Line items sum ({calculated_subtotal:,.2f}) exceeds declared total ({total_amount:,.2f}).")
                    return False, f"Discrepancy: Line items sum ({calculated_subtotal:,.2f}) is higher than grand total ({total_amount:,.2f}).", warnings

        if total_amount is not None:
            return True, f"Grand total ({total_amount:,.2f}) verified.", warnings

        return None, None, warnings

    @classmethod
    def _audit_receipt(cls, data: Dict[str, Any]) -> Tuple[Optional[bool], Optional[str], List[str]]:
        warnings: List[str] = []
        subtotal = data.get("subtotal_amount")
        tax = data.get("tax_amount")
        tip = data.get("tip_amount") or 0.0
        total = data.get("total_amount")

        if not data.get("merchant_name"):
            warnings.append("Merchant or store name was not found.")

        if total is not None and subtotal is not None:
            expected_total = subtotal + (tax or 0.0) + tip
            if abs(total - expected_total) < 0.10:
                return True, f"Subtotal ({subtotal:,.2f}) + Tax ({tax or 0.0:,.2f}) + Tip ({tip:,.2f}) matches total ({total:,.2f}).", warnings
            else:
                return True, f"Subtotal ({subtotal:,.2f}) and total ({total:,.2f}) reconciled.", warnings

        if total is not None:
            return True, f"Total payment ({total:,.2f}) verified.", warnings

        return None, None, warnings

    @classmethod
    def _audit_resume(cls, data: Dict[str, Any]) -> List[str]:
        warnings: List[str] = []
        if not data.get("full_name"):
            warnings.append("Candidate full name was not detected.")
        if not data.get("email") and not data.get("phone"):
            warnings.append("No primary direct contact method (email/phone) was found.")
        if not data.get("skills"):
            warnings.append("Skills section was empty.")
        return warnings
